import itertools

def shortest_superstring(a, b, c):
    strings = [a, b, c]
    best = None

    def merge(s1, s2):
        # If s2 is a substring of s1, s1 already contains s2
        if s2 in s1:
            return s1
        # If s1 is a substring of s2, s2 already contains s1
        if s1 in s2:
            return s2

        max_overlap = 0
        # Check for maximum overlap where suffix of s1 matches prefix of s2
        # The overlap length k can be at most min(len(s1), len(s2))
        for k in range(1, min(len(s1), len(s2)) + 1):
            if s1.endswith(s2[:k]):
                max_overlap = k

        # Merge s1 and s2 with the maximum overlap
        return s1 + s2[max_overlap:]

    # Iterate over all permutations of the three strings
    for p in itertools.permutations(strings):
        # Merge the first two strings in the permutation
        res = merge(p[0], p[1])
        # Merge the result with the third string
        res = merge(res, p[2])

        # Update the best result found so far
        if best is None:
            best = res
        else:
            if len(res) < len(best):
                best = res
            elif len(res) == len(best):
                if res < best:
                    best = res

    return best
